import { MeshBasicNodeMaterial } from 'three/webgpu';
import { gsap } from 'gsap';
import * as primitives from '@/primitives';
import * as text from '@/text';

export default function createNode(config, ctx) {
  const { Group, Mesh, PlaneGeometry, Color } = ctx.THREE;

  // Root container – position/rotation/scale are applied by the adapter.
  const root = new Group();

  // ---------- BACKDROP PLANE ----------
  const planeGeom = new PlaneGeometry(7, 6);
  const planeMat = new MeshBasicNodeMaterial();
  // Base surface color from visual spec or default.
  const surfaceColor = config.intent?.visualSpec?.colors?.surface ?? '#0b0b10';
  planeMat.color = new Color(surfaceColor);

  // Load texture if an image URL is provided.
  if (config.imageUrl) {
    ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
      planeMat.map = tex;
      planeMat.needsUpdate = true;
    });
  }

  const planeMesh = new Mesh(planeGeom, planeMat);
  planeMesh.position.set(0, 0, 0);
  root.add(planeMesh);

  // ---------- TEXT CONTENT ----------
  const items =
    config.textContent ??
    config.intent?.visualSpec?.textContent ??
    [];

  for (const item of items) {
    const txtOpts = {
      fontSize: item.typography?.fontSize ?? 31,
      color: config.intent?.visualSpec?.colors?.ink ?? '#16161d',
      align: 'left',
    };
    const txtObj = ctx.fontAtlas.createText(item.text, txtOpts);
    // Position text slightly in front of the plane to avoid z‑fighting.
    txtObj.position.set(0, 0, 0.01);
    root.add(txtObj);
  }

  // ---------- PRIMITIVES (none in this spec) ----------
  const primitiveHandles = [];

  // ---------- EVENT HANDLERS ----------
  root.userData.handlers = {};

  // ---------- CLEANUP ----------
  root.userData.cleanup = () => {
    // Dispose material & geometry.
    planeMat.dispose();
    planeGeom.dispose();
    if (planeMat.map) {
      planeMat.map.dispose();
    }
    // Dispose any primitive handles (none here).
    for (const h of primitiveHandles) {
      if (h && typeof h.cleanup === 'function') h.cleanup();
    }
    // Kill any GSAP timelines that might have been created elsewhere.
    if (root.userData._timelines) {
      for (const tl of root.userData._timelines) tl.kill();
    }
  };

  return root;
}
